-- Local authorization fixtures only; rolled back, never a hosted project.
begin;
create function pg_temp.assert_true(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;end;$$;
create function pg_temp.expect_error(q text,code text) returns void language plpgsql as $$declare actual text;begin begin execute q;exception when others then get stacked diagnostics actual=returned_sqlstate;if actual<>code then raise exception 'FAIL expected %, got %: %',code,actual,q;end if;return;end;raise exception 'FAIL expected rejection: %',q;end;$$;
create function pg_temp.x(n integer) returns uuid language sql as $$select ('d8000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.a() returns uuid language sql as $$select 'd1000000-0000-4000-8000-000000000001'::uuid$$;
create function pg_temp.b() returns uuid language sql as $$select '50000000-0000-4000-8000-000000000002'::uuid$$;
create function pg_temp.chat_path(owner_id uuid,draft integer,image integer) returns text language sql as $$select owner_id::text||'/chat/'||pg_temp.x(1)::text||'/'||pg_temp.x(draft)::text||'/'||pg_temp.x(image)::text||'.jpg'$$;
insert into auth.users(id,raw_user_meta_data) values(pg_temp.a(),'{"full_name":"Tailor requester A"}'),(pg_temp.x(100),'{"full_name":"Unrelated account"}'),(pg_temp.x(101),'{"full_name":"Customer requester"}');
